/*
 * Geometry – sample-domain layout for a given sample rate.
 */
typedef struct {
    uint32_t sr;                /* sample rate */
    uint32_t spl;               /* samples per line */
    uint32_t half;              /* samples per half-line */
    uint32_t hsync;             /* hsync width in samples */
    uint32_t eq;                /* equalizing pulse width */
    uint32_t broad;             /* broad pulse width */
    uint32_t active_off;        /* active start offset in line */
    uint32_t active;            /* active region samples */
    uint32_t pad;               /* extra lead-in samples */
    double   nominal_spb;       /* nominal samples per bit */
    uint32_t field_samples;     /* total samples per field */
    /* bit_map is large; compute on the fly or allocate separately if needed */
} Geometry;

/* Convert microseconds to samples at the given rate */
static inline uint32_t us_to_samples(uint32_t sample_rate, double us)
{
    return (uint32_t)(sample_rate * us * 1e-6 + 0.5);
}

/* Initialise a Geometry structure for the given sample rate */
static inline void geometry_init(Geometry *g, uint32_t sample_rate)
{
    g->sr         = sample_rate;
    g->spl        = us_to_samples(sample_rate, LINE_US);
    g->half       = us_to_samples(sample_rate, HALF_LINE_US);
    g->hsync      = us_to_samples(sample_rate, HSYNC_US);
    g->eq         = us_to_samples(sample_rate, EQ_US);
    g->broad      = us_to_samples(sample_rate, BROAD_US);
    g->active_off = us_to_samples(sample_rate, HSYNC_US + BACKPORCH_US);
    g->active     = us_to_samples(sample_rate, ACTIVE_US);
    g->pad        = us_to_samples(sample_rate, 1.0);
    g->nominal_spb = (double)g->active / (double)TOTAL_BITS_PER_LINE;
    g->field_samples = 15 * g->half + (VBI_LINES + DATA_LINES) * g->spl;
}

/* Absolute sample offset of a data line's hsync (clean signal) */
static inline uint32_t data_line_start(const Geometry *g,
                                       uint32_t field_idx,
                                       uint32_t line_idx)
{
    return field_idx * g->field_samples
         + 15 * g->half
         + (VBI_LINES + line_idx) * g->spl;
}

/* Bit index for a given active sample (uniform fractional bit widths).
 * Equivalent to Python: (sample_idx * TOTAL_BITS_PER_LINE) // active */
static inline uint32_t bit_map(const Geometry *g, uint32_t sample_idx)
{
    return (sample_idx * TOTAL_BITS_PER_LINE) / g->active;
}

